// Renders a demo page frame by frame, encodes it to MP4 with ffmpeg,
// then adds the background track generated by music.py.
// The page sets window.DURATION, and optionally window.VIEW ({w, h}) and
// window.MUSIC_ARGS (extra music.py flags).
// Usage: node render.js [out.mp4] [--page demo.html] [--stills t1,t2,... outdir]
const { chromium } = require('playwright');
const { spawn, execFileSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const FPS = 30;
(async () => {
  const args = process.argv.slice(2);
  const opt = name => { const i = args.indexOf(name); return i >= 0 ? args.slice(i + 1) : null; };
  const pageFile = (opt('--page') || ['demo.html'])[0];
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('file://' + path.join(__dirname, pageFile));
  await page.evaluate(() => document.fonts.ready);
  const view = await page.evaluate(() => window.VIEW || { w: 1920, h: 1080 });
  await page.setViewportSize({ width: view.w, height: view.h });
  const stills = opt('--stills');
  if (stills) {
    for (const t of stills[0].split(',').map(Number)) {
      await page.evaluate(t => window.__render(t), t);
      await page.screenshot({ path: `${stills[1] || '.'}/still-${t}.png` });
    }
    return browser.close();
  }
  const out = args[0] && !args[0].startsWith('--') ? args[0] : path.join(__dirname, 'decision-coach-demo.mp4');
  const dur = await page.evaluate(() => window.DURATION);
  const musicArgs = await page.evaluate(() => window.MUSIC_ARGS || []);
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'demo-'));
  const music = path.join(tmp, 'music.wav');
  const silent = path.join(tmp, 'video.mp4');
  execFileSync('python3', [path.join(__dirname, 'music.py'), music, String(dur), ...musicArgs], { stdio: 'inherit' });
  const ff = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(FPS), '-i', '-',
    '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-crf', '20', '-preset', 'medium', silent], { stdio: ['pipe', 'inherit', 'inherit'] });
  const frames = Math.round(dur * FPS);
  for (let i = 0; i < frames; i++) {
    await page.evaluate(t => window.__render(t), i / FPS);
    const buf = await page.screenshot({ type: 'jpeg', quality: 92 });
    if (!ff.stdin.write(buf)) await new Promise(r => ff.stdin.once('drain', r));
    if (i % 300 === 0) console.log(`frame ${i}/${frames}`);
  }
  ff.stdin.end();
  await new Promise(r => ff.on('close', r));
  await browser.close();
  execFileSync('ffmpeg', ['-y', '-loglevel', 'error', '-i', silent, '-i', music, '-c:v', 'copy',
    '-c:a', 'aac', '-b:a', '192k', '-shortest', '-movflags', '+faststart', out], { stdio: 'inherit' });
  fs.rmSync(tmp, { recursive: true, force: true });
  console.log('wrote', out);
})();
